  "customKeys.title": "Vos propres touches",
  "customKeys.intro": "Placez n’importe quelle commande de la recherche de commandes sur une touche de votre choix : un outil, une forme, Centrer sur le plan de travail, le panneau des formes. Vos touches restent dans ce navigateur.",
