  "interactiveHelp.started": "L'aide interactive est activée : cliquez sur un bouton, un champ ou une fenêtre pour en savoir plus. Échap la quitte.",
  "interactiveHelp.ended": "L'aide interactive est désactivée",
  "shortcuts.interactiveHelp": "Activer ou désactiver l'aide interactive",
  "installHint.chromium": "Installez-le avec l'icône à droite de la barre d'adresse, ou depuis le menu du navigateur sous « Installer en tant qu'application ».",
  "installHint.safariMac": "Dans Safari : Menu Fichier → « Ajouter au Dock ».",
  "installHint.ios": "Dans Safari : icône Partager → « Ajouter à l'écran d'accueil ».",
  "installHint.firefox": "Firefox ne peut pas installer d'applications – le layering démarre toujours hors ligne ici dans l'onglet.",
  "welcome.moreLanguagesTitle": "Votre langue",
  "welcome.moreLanguagesBody": "le programme et son guide parlent anglais, allemand et 17 autres langues ; la liste des langues se trouve tout en haut à droite et dans les réglages de la page d'accueil.",
  "welcome.moreOfflineTitle": "Fonctionne hors ligne",
  "welcome.moreOfflineBody": "après la première visite, le layerling démarre également sans Internet - installez-le comme un programme normal, vos créations restent sur votre ordinateur.",
  "welcome.moreAiTitle": "Construire avec l'IA",
  "welcome.moreAiBody": "Grâce à l'interface MCP, un assistant IA peut créer et modifier des formes, dans un éditeur qu'il ouvre lui-même. Cela nécessite une copie que vous exécutez vous-même (npm run dev ou l'image Docker) ; sur layerling.com, la connexion AI est désactivée.",
  "welcome.morePointsTitle": "Points de référence",
  "welcome.moreSearchTitle": "Recherche de commandes",
  "welcome.moreSimplifyTitle": "Simplifier les maillages",
  "welcome.moreSimplifyBody": "Un maillage importé avec un très grand nombre de triangles est réduit à une fraction, avec une vue avant et après et un curseur - ainsi la coupe, le regroupement et le déplacement restent fluides.",
  "welcome.moreHistoryTitle": "Histoire",
  "welcome.moreLookTitle": "Regardez comme vous l'aimez",
  "welcome.moreLookBody": "L'arrière-plan et le plan de travail, les flèches des axes X, Y et Z, les lignes de bord sur chaque corps, les couleurs de l'esquisse et le contraste, les ombres et la direction de la lumière sont à vous de définir dans les paramètres - par exemple pour que les corps sombres ne se croisent pas. Sur les ordinateurs plus lents, le mode rapide désactive tout ce qui coûte cher en même temps.",
  "welcome.moreControlsTitle": "Souris et souris 3D",
  "welcome.moreControlsBody": "fait fonctionner les boutons de la souris comme dans Bambu Studio et OrcaSlicer si tu veux - un glisser gauche sur une zone vide fait tourner la vue, le bouton droit la déplace - et pilote la vue avec une SpaceMouse dans Chrome et Edge.",
  "welcome.moreTabletTitle": "Sur une tablette",
  "welcome.moreTabletBody": "un doigt agit sur le projet comme le bouton gauche de la souris, deux doigts zooment et déplacent la vue ; un clavier Bluetooth apporte les raccourcis.",
  "welcome.moreHistoryBody": "revenez sur n'importe quel état antérieur du projet avec un curseur, sans rien changer - exportez cet état, démarrez un nouveau projet à partir de celui-ci ou ramenez-en des objets isolés. Annuler et Rétablir nomment l'étape qu'ils reprennent, avec sa mesure, et une liste nomme chaque étape vers laquelle sauter.",
  "welcome.moreDrawingTitle": "Dessin pour l'atelier",
  "welcome.moreDrawingBody": "Exporter → Dessin : vues de face, de dessus et de côté au 1:1 sur une feuille ISO, avec dimensions hors tout, bords cachés et tableau des alésages ronds – au format PDF ou SVG, à imprimer ou à emporter au tour et à la fraiseuse. La vue de dessus en SVG ou DXF part vers la découpe laser, avec si vous le souhaitez des ponts de pochoir qui tiennent le milieu d'un o ou d'un b.",
  "welcome.moreSearchBody": "Appuyez sur Ctrl+K et tapez le nom d'un outil, d'une forme ou d'une commande pour y accéder directement - en anglais ou en allemand, avec les raccourcis clavier affichés à côté de chacun. Les corps de votre conception sont également trouvés par leur nom. Chacune peut aussi aller sur une touche de votre choix.",
  "welcome.moreHelpTitle": "Aide interactive",
  "welcome.moreHelpBody": "appuyez sur Maj+F1 ou sur le point d'interrogation, puis cliquez sur un bouton, un champ ou une fenêtre : une petite fenêtre montre la partie du guide qui en parle.",
  "welcome.morePointsBody": "cliquez avec le bouton droit sur un corps pour marquer son centre, ses coins ou le milieu de ses bords avec des points que rien n'imprime et sur lesquels les formes s'accrochent - puis placez un trou exactement au centre d'une autre pièce.",
  "welcome.videosTitle": "Vidéos sur layerling",
  "welcome.videosHint": "Fabriqué par d'autres, pas par ce projet. Les liens ouvrent YouTube dans un nouvel onglet ; rien n'est chargé à partir de là jusqu'à ce que vous cliquiez.",
  "welcome.help": "Dans l'éditeur, le groupe Aide contient un petit guide et la liste de tous les raccourcis clavier. Dans le pied de page, « Rapport de bug » enregistre votre conception avec tout le nécessaire pour un rapport sur le forum ou sur GitHub.",
  "welcome.guideLink": "Lire le guide d'utilisation complet, avec des images",
  "welcome.guideUrl": "/guide/index.html",
