  "status.lidMadeMagnetsPosts": "Couvercle créé ({type}) avec {count} cavités d'aimant, dans le couvercle et dans des piliers aux coins du corps, là où sa paroi était trop fine. Le couvercle est posé retourné à côté du corps, prêt à imprimer.",
  "status.lidMadeHinge": "Couvercle créé ({type}) avec une charnière : {count} nœuds et un trou pour un axe de {pin} mm. Le couvercle est posé retourné à côté du corps, prêt à imprimer.",
  "status.lidMadeHingeMagnets": "Couvercle créé ({type}) avec une charnière ({count} nœuds, axe de {pin} mm) et {magnets} logements d'aimant. Le couvercle est posé retourné à côté du corps, prêt à imprimer.",
  "status.lidClickBumps": "{count} picots de clipsage du couvercle s'enclenchent dans des creux du corps.",
  "status.lidHandleTab": "Le couvercle a une languette sur le bord par lequel il s'ouvre.",
  "status.lidHandleNotch": "Une encoche pour le doigt est découpée dans la paroi du corps sous le bord du couvercle, du côté où il s'ouvre.",
  "status.lidMadeScrew": "Couvercle à vis créé : le corps a un filetage en haut, à l'extérieur (pas de {pitch} mm, {height} mm de haut), et le couvercle, {diameter} mm de large, est posé retourné à côté, prêt à imprimer.",
  "status.lidMadeScrewStandard": "Couvercle à vis pour {standard} créé : le corps a le filetage du col en haut, à l'extérieur (pas de {pitch} mm), et le couvercle, {diameter} mm de large, est posé retourné à côté, prêt à imprimer.",
  "status.lidMadeScrewCapOnly": "Couvercle à vis pour {standard} créé : {diameter} mm de large, il est posé retourné à côté du corps, prêt à imprimer. Le haut du corps fait {measured} mm de large, pas {neck} mm comme le col sous le filetage, il reste donc tel quel.",
  "status.lidMadeScrewCapOnlyNotRound": "Couvercle à vis pour {standard} créé : {diameter} mm de large, il est posé retourné à côté du corps, prêt à imprimer. Le haut du corps n'est pas rond, il reste donc tel quel.",
  "status.lidMadeScrewIn": "Couvercle vissé dedans créé : le corps a un filetage à l'intérieur de son ouverture (pas de {pitch} mm, {height} mm de profondeur), et le couvercle, avec un bouchon de {diameter} mm de large, est posé retourné à côté, prêt à imprimer. Tourne-le dans le sens des aiguilles d'une montre pour le fermer.",
  "status.lidMadeBayonet": "Couvercle à baïonnette créé : le corps a en haut, à l'extérieur, {count} ergots qui dépassent de {height} mm, et le couvercle, {diameter} mm de large, est posé retourné à côté, prêt à imprimer. Enfonce-le et tourne-le de {turn}° dans le sens des aiguilles d'une montre pour le verrouiller.",
  "status.lidMadeSlide": "Couvercle coulissant créé : des rainures de {depth} mm de profondeur dans trois parois du corps, et la quatrième abaissée pour que le couvercle glisse par-dessus. Le couvercle est posé retourné à côté du corps, prêt à imprimer.",
  "status.lidSlideBump": "Un picot sous le couvercle le fait se clipser.",
  "status.lidSlideGrip": "Des rainures en travers du dessus du couvercle offrent une prise au pouce.",
