  "guide.edges.offset": "Le décalage déplace chaque face d'un corps de la même distance, vers l'extérieur ou l'intérieur. Agrandis une copie et garde-la comme trou pour obtenir le jeu d'un ajustement, ou réduis un corps pour un tenon qui doit entrer dans un trou. Les corps qui ne sont qu'un maillage de triangles ne peuvent souvent pas être décalés.",
