  "deleteFace.errorFailed": "Les faces n'ont pas pu être supprimées. Veuillez choisir d'autres faces.",
  "deleteFace.errorNoFaces": "Les faces de ce corps n'ont pas pu être lues. Fermez l'outil et rouvrez-le.",
  "deleteFace.errorTooSlow": "La suppression de ces faces a pris trop de temps et a été arrêtée au bout de 45 secondes ; rien n'a changé. Le noyau CAO ne s'en sort pas avec ces faces sur cette pièce : choisissez d'autres faces, ou moins de faces.",
  "status.facesDeletedOne": "1 face supprimée",
