  "paint.wholeFaces": "Ce maillage n'est pas fermé : les cercles et les lassos suivent ses triangles.",
  "status.honeycombConverted": "Nid d'abeille converti en motif de trous : {count}",
  "welcome.moreHolePatternTitle": "Modèle de trou",
  "welcome.moreHolePatternBody": "Cliquez sur une face plane d'un corps et répartissez dessus des trous : ronds, carrés, rectangulaires, hexagonaux ou fentes, en quadrillage ou en quinconce, avec espacement, marge au bord et profondeur (sur tout le corps ou une profondeur définie). Un aperçu montre les trous avant de les créer ; ce sont des trous ordinaires, regroupés avec le corps - pour les évents, les grilles d'enceintes, les paniers et les enceintes. Ou placez une couronne de trous de vis le long du bord, un à chaque coin, avec lamage ou fraisage si vous le souhaitez. Une forme personnalisée se répète de la même façon, des rivets ou une tôle larmée. Sur la paroi ronde d'un cylindre ou d'un tube, les trous font tout le tour, chacun pointé vers l'axe.",
  "welcome.moreSupportRibTitle": "Nervure de support",
  "welcome.moreSupportRibBody": "Imprimez une pièce inclinée sur une arête sans les supports du slicer : cliquez sur sa face inférieure et une fine nervure se place dessous, à petite distance, sur un pied ovale, avec de minuscules ponts d'exactement une couche qui tiennent la pièce et se cassent ensuite.",
  "welcome.moreStencilBridgesTitle": "Ponts de pochoir",
  "welcome.moreStencilBridgesBody": "Imprimez un pochoir avec un texte qui traverse la plaque : le centre des lettres comme o, a et b reçoit de petits ponts vers la plaque, aussi larges et hauts que vous voulez, pour que rien ne tombe.",
  "welcome.moreFaceTitle": "Pousser une face",
  "welcome.moreFaceBody": "sortir une face plane d'un corps ou y creuser une poche, avec un retrait depuis le bord, des coins arrondis et une profondeur, en aperçu - aussi sur des STL importés.",
  "welcome.moreTextureTitle": "Texture de surface",
  "welcome.moreTextureBody": "posez un relief sur n'importe quel corps, pour la prise en main ou pour l'aspect - moletage, rainures, nid d'abeille, veinage du bois, corde, une image comme carte de hauteur ou du texte, autour des corps ronds ou à plat le long d'un axe. Jusqu'à six motifs sur un même corps, chacun sur ses propres faces. Pour une impression en deux couleurs, le motif peut aussi devenir une pièce à part, dans sa propre couleur.",
  "welcome.moreVaseTitle": "Vases et pots",
  "welcome.moreVaseBody": "une forme à part pour les vases, pots et abat-jour : forme du corps, section, torsion, motifs, trous de drainage, soucoupe et couvercle - plein pour le mode vase du trancheur ou creux. Un couvercle de théière reprend le haut du vase lui-même, le motif se poursuivant par-delà le joint.",
  "welcome.moreOffsetTitle": "Décaler et découper",
  "welcome.moreOffsetBody": "faites grossir ou rétrécir un corps exact d'une distance donnée, tout autour ou seulement sur les côtés, pour le jeu d'un ajustement serré, ou découpez une pièce dans une autre avec un jeu tout autour, en une seule étape.",
  "welcome.morePunchTitle": "Poinçonner",
  "welcome.morePunchBody": "découpe le contour d'un corps tout droit à travers un autre, où qu'il se trouve devant : la silhouette d'une théière à travers une plaque, un logo à travers un couvercle. Déplacez ou tournez le poinçon et recommencez ; un jeu laisse passer une pièce imprimée.",
  "welcome.moreClearanceTitle": "Vérifier le jeu",
  "welcome.moreClearanceBody": "avant d'imprimer des pièces qui doivent bouger - une charnière imprimée en place, un jouet flexi, un couvercle dans sa boîte - trouve les paires qui se chevauchent, se touchent ou sont plus proches que le jeu que vous fixez.",
  "guide.select.holePattern": "Motif de trou (le bouton du ruban à côté de Motif, cliquez avec le bouton droit sur un corps ou Ctrl+K) : cliquez sur une face plate ou une paroi ronde, puis définissez la forme, la taille, l'espacement, la disposition, la marge et la profondeur du trou. Les trous s'affichent à titre d'aperçu ; \"Créer\" les ajoute sous forme de trous regroupés avec le corps. Dissocier les libère à nouveau.",
  "guide.select.faceTool": "Face (le bouton du ruban à côté de Modèle de trou, clic droit sur un corps ou Ctrl+K) : cliquez sur une face plane, choisissez vers l'extérieur ou vers l'intérieur, puis réglez le retrait depuis le bord, le rayon des coins et la profondeur. Ce qui est ajouté est un corps d'esquisse regroupé avec le corps.",
  "guide.select.supportRib": "Nervure de support (bouton du ruban, clic droit sur un corps ou Ctrl+K) : cliquez sur la face inférieure d'une pièce imprimée inclinée sur une arête. Une fine nervure se place dessous à petite distance, sur un pied ovale, tenue à la pièce par de petits ponts d'une couche de haut ; réglez la buse et les couches de votre slicer.",
  "scalePercent.errorTooSmall": "\"{name}\" deviendrait inférieur à 0,01 mm.",
  "scalePercent.errorTooLarge": "\"{name}\" deviendrait plus grand que sa forme ne le permet. Définissez une « limite de taille personnalisée » plus élevée sous Paramètres de forme par défaut dans les paramètres, ou choisissez un pourcentage plus petit.",
  "status.scaledByPercent": "A l'échelle de {percent} %",
