  "status.meshTooDense": "Ce maillage comporte des triangles {triangles}. Le traitement des bords gère {limit} ; au-delà de cela, le noyau prend plus de temps que n'importe quelle attente. Pour une forme de la liste de formes, utilisez pour l’instant ses propres paramètres. Pour une pièce importée, importez-la au format STEP ou enregistrez-la d'abord avec moins de triangles.",
  "status.meshDenseAsk": "Ce maillage compte {triangles} triangles, plus que les {limit} pour lesquels le traitement des arêtes est conçu. Au-delà, cela peut durer de nombreuses minutes, la page peut se figer et tout ce qui n'est pas enregistré est perdu si vous devez la fermer. Enregistrez d'abord votre projet.\n\nEssayer quand même ?",
  "status.threadTooDense": "Un thread est construit à partir de triangles {triangles} — trop nombreux pour le traitement des bords, qui s'arrêtent à {limit}. Ajoutez donc le filetage après le traitement des bords : chanfreinez ou arrondissez d'abord le corps, puis le filetage. Le chanfrein de la tête dans les propriétés brise le bord de la tête de vis sans ce détour.",
  "status.vaseTooDense": "Ce vase compte {triangles} triangles, plus que les {limit} que l'évidement et le traitement des bords peuvent gérer. Le vase se creuse lui-même et a son propre couvercle : choisis « Creux avec paroi » sous Construction et un couvercle sur la carte Accessoires.",
