  "screwBoss.screwOption": "{size} – avant-trou {hole} mm",
  "screwBoss.insertHint": "Le trou est un millimètre plus profond que l'insert. Les trous imprimés sortent un peu plus petits que dessinés : imprimez un bossage pour essayer et ajustez le trou d'un ou deux dixièmes.",
  "screwBoss.screwHint": "Avant-trou d'environ 0,8 fois la vis, bossage d'environ 2,5 fois, trou profond de 2,5 vis. Les trous imprimés sortent un peu plus petits : essayez d'abord.",
  "screwBoss.customHint": "Saisissez le trou dont vous avez besoin, par exemple 3,4 mm pour une vis M3 qui traverse.",
  "screwBoss.through": "Aussi profond que le bossage : le trou traverse.",
  "screwBoss.wall": "Paroi autour du trou : {wall} mm.",
  "screwBoss.wallThin": "Paroi autour du trou de seulement {wall} mm – cette fixation demande au moins {min} mm. Élargissez le bossage.",
  "screwBoss.gussetsHint": "De fines nervures du bossage jusqu'au fond le renforcent ; 3 ou 4 sont courantes.",
  "screwBoss.gussetsNoRoom": "Il n'y a pas la place pour autant : goussets plus fins ou largeur plus grande.",
  "prop.snapFitPart": "Pièce",
