  "snapFit.hook": "Crochet seul",
  "snapFit.catch": "Butée seule",
  "snapFit.bothHint": "Les deux sont placés comme une fois encliquetés, le couvercle en haut : le socle du crochet sous le couvercle, le dos de la butée contre l'intérieur de la paroi du boîtier, puis Séparer les pièces les sépare.",
  "snapFit.hookHint": "Le crochet seul, pour une fenêtre dans la paroi ou votre propre butée.",
  "snapFit.catchHint": "Seulement la réglette sous laquelle le crochet s'engage ; son dos va contre la paroi.",
  "snapFit.strainFine": "S'allonge de {strain} % à sa base en s'encliquetant : convient au PLA (jusqu'à environ 2 %).",
  "snapFit.strainTough": "S'allonge de {strain} % à sa base : trop pour le PLA, bien pour le PETG ou l'ABS (jusqu'à environ 4 %). Un bras plus long ou plus fin plie moins.",
  "snapFit.strainTooMuch": "S'allonge de {strain} % à sa base : il cassera. Allongez ou amincissez le bras, ou réduisez la contre-dépouille.",
  "snapFit.leadHint": "Mesuré par rapport au sens d'insertion : 30° entre facilement, moins entre plus doucement.",
  "snapFit.retainHint": "90° tient pour de bon, 45° permet de le défaire.",
  "snapFit.footHint": "La plaque à laquelle pend le bras, reliée au couvercle. 0 : sans socle.",
  "prop.ribStyle": "Type",
  "prop.ribLength": "Longueur",
