  "status.gridfinityKeysNone": "Ce socle n'a pas de cavité à l'arrière ni à droite, car ces côtés ont une bordure ; il n'apporte donc pas d'agrafes. Réglez la bordure de l'un d'eux sur 0 pour lui donner des cavités.",
