  "inspector.surfaceCrackSeedHint": "Même graine, mêmes fissures – une autre les tire à nouveau. La longueur compte en % de la hauteur, du bord vers le centre en % du rayon.",
  "inspector.surfaceCrackGold": "Remplissage d'or en pièce à part",
  "inspector.surfaceCrackRecess": "Or en retrait",
  "inspector.surfaceCrackGoldHint": "Le remplissage des fissures devient une pièce à part en or, pour un second filament ; son dessus se trouve à cette profondeur sous la surface. Pour cela, le motif va vers l'intérieur.",
  "inspector.surfacePatternPart": "Motif en pièce à part",
  "inspector.surfacePatternColor": "Couleur du motif",
  "inspector.surfacePatternRaisedHint": "Ce qui ressort du corps devient une pièce à part dans cette couleur, pour un second filament ; le corps reste tel qu'il était. Les deux forment un lot : ils se déplacent ensemble, et la texture peut toujours être changée ou retirée.",
  "inspector.surfacePatternCutHint": "Ce qui est creusé dans le corps devient une pièce à part dans cette couleur, qui remplit le creux jusqu'à la surface, pour un second filament. Les deux forment un lot : ils se déplacent ensemble, et la texture peut toujours être changée ou retirée.",
  "inspector.surfacePatternWayHint": "Seulement pour un motif vers l'extérieur ou vers l'intérieur, dans le même sens sur chaque calque : tel qu'il est réglé, le motif reste d'un seul tenant avec le corps.",
  "status.surfaceNoCracks": "Aucune fissure n'a trouvé de chemin sur ce corps. Essayez un autre départ (« N'importe où » va sur tout corps), des fissures plus longues, ou laissez le motif sur plus de faces.",
  "status.surfaceCracks": "{count} lignes de fissure, {length} mm en tout.",
  "status.surfaceGold": "Le remplissage d'or se trouve dans les fissures en pièce à part.",
