  "surfaceTexture.carbonTwill31": "Sergé 3/1",
  "surfaceTexture.carbonTwill22Hint": "Chaque bande passe sur deux bandes transversales et sous deux : la diagonale régulière de la plupart des pièces en carbone.",
  "surfaceTexture.carbonTwill21Hint": "Sur deux, sous une : les bandes verticales se montrent longues, les transversales courtes.",
