  "inspector.surfaceImageBlur": "Adoucir",
  "inspector.surfaceImageTiling": "Tuiles",
  "inspector.surfaceGrainHint": "Le grain est posé dans l'espace plutôt que projeté : sans couture ni étirement, le même sur toute forme.",
