  "surfaceTexture.woodCutQuarterSawn": "Planche, débit sur quartier",
  "surfaceTexture.woodCutLogHint": "La moelle traverse le corps en son milieu : les extrémités montrent les cernes, les côtés la veinure d'un tronc sans écorce.",
  "surfaceTexture.woodCutFlatSawnHint": "La moelle passe sous la planche le long de son plus grand côté : les cernes coupent la face en arcs.",
  "surfaceTexture.woodCutQuarterSawnHint": "La moelle passe à côté de la planche : les cernes coupent la face en lignes droites, et le chêne montre ses rayons en maillure.",
  "inspector.surfaceRingWidth": "Largeur des cernes",
  "inspector.surfaceEndRings": "Cernes en haut et en bas",
  "inspector.surfaceWoodHint": "La veinure est dans le corps comme dans un vrai morceau de bois : des cernes étroits donnent une veinure fine, des larges une veinure grossière, et les extrémités montrent des cernes assortis aux côtés.",
  "inspector.surfaceWoodKnots": "Nœuds",
