  "surfaceTexture.bondFlemish": "Appareil flamand",
  "surfaceTexture.bondRunningHint": "Chaque assise décalée d'une demi-brique, comme la plupart des murs.",
  "surfaceTexture.bondStackHint": "Les joints en une ligne, assise sur assise, comme on pose du carrelage.",
  "surfaceTexture.bondEnglishHint": "Une assise de briques longues (panneresses), puis une de courtes (boutisses, deux fois plus courtes), en alternance.",
  "surfaceTexture.bondEnglishCrossHint": "Comme l'appareil anglais, et une assise de panneresses sur deux décalée d'une demi-brique.",
  "surfaceTexture.bondFlemishHint": "Dans chaque assise, une brique longue et une courte en alternance, chaque courte au-dessus du milieu d'une longue.",
  "inspector.surfaceBrickHint": "Longueur et hauteur se comptent d'un joint à l'autre. Elles sont un peu arrondies pour que des briques entières tiennent : autour d'un corps rond, d'un bord à l'autre d'une face plane et du bas jusqu'en haut.",
  "inspector.surfaceBrickVary": "Briques inégales (%)",
  "inspector.surfaceBrickVaryHint": "Chaque brique est un peu plus profonde, chacune à sa façon – à 100 % jusqu'à la moitié de la profondeur. Un autre nombre, un autre mur.",
  "surfaceTexture.squares": "Carrés",
