  "inspector.surfaceTileFromBottom": "Depuis le bord inférieur",
  "inspector.surfaceTileHint": "La taille et l'écart restent exactement comme réglés, le motif centré sur chaque face ; autour d'un corps rond, l'écart est un peu arrondi pour qu'un nombre entier en fasse le tour. Depuis le bord inférieur, la première rangée commence tout en bas et descend jusqu'à la première couche – pour une bordure (brim).",
  "inspector.surfaceTileProfileHint": "Plat donne des parois raides ; pointu fait des pyramides, rond et demi-rond des coussins.",
