  "surfaceTexture.timberKnee": "Aisseliers",
  "surfaceTexture.timberMixed": "Mélangé",
  "surfaceTexture.timberNoneHint": "Seulement des poutres verticales et horizontales.",
  "surfaceTexture.timberBracesHint": "Une écharpe dans chaque panneau, penchée vers le milieu depuis les deux bouts.",
  "surfaceTexture.timberCrossHint": "Un X dans le panneau sous la traverse la plus basse.",
  "surfaceTexture.timberKneeHint": "De courtes pièces obliques dans les coins du haut de chaque panneau.",
  "surfaceTexture.timberMixedHint": "Des écharpes aux deux bouts, puis des croix et des aisseliers en alternance vers le milieu.",
  "inspector.surfaceTimberGrain": "Veinage du bois (%)",
  "inspector.surfaceTimberGrainHint": "0 % : aucun. Sous 50 % plus fin : davantage de rainures, plus étroites et moins profondes. Au-dessus de 50 % plus marqué : deux rainures larges et profondes. 50 % : comme au départ.",
  "inspector.surfaceTimberHint": "La largeur des panneaux (d'un poteau à l'autre) et la hauteur d'étage sont un peu arrondies pour que des panneaux entiers tiennent : autour d'un corps rond, d'un bord à l'autre d'une face plane et à partir du bord inférieur. Les poutres ressortent, l'enduit entre elles est plus bas.",
  "surfaceTexture.stones": "Mur en pierre",
