  "vaseCheck.conflictLamp": "l'abat-jour",
  "vaseCheck.watertightHollow": "Étanche : paroi et fond d'au moins {mm} mm ; dans le trancheur, au moins trois lignes de paroi et cinq couches de fond, plutôt un peu plus de débit ou de température. Testez d'abord avec de l'eau au-dessus de l'évier.",
  "vaseCheck.watertightVaseMode": "Étanche en mode vase : une ligne plus large (environ 0,6–0,8 mm avec une buse de 0,4 mm) et un peu plus de température rendent la paroi unique étanche ; des nervures intérieures ou une double paroi la renforcent. Testez d'abord avec de l'eau au-dessus de l'évier.",
