  "vaseCheck.lampHoleTooBig": "Le trou pour la douille (Ø {mm} mm) ne tient pas dans le fond – élargissez le vase en bas.",
  "vaseCheck.lampNoDrains": "Un abat-jour a le trou pour la douille au lieu de trous d'écoulement.",
  "vaseCheck.lampHanging": "Suspendu : retournez-le pour le suspendre – la plaque percée (Ø {mm} mm) se pose sur la douille et est tenue par la bague d'abat-jour. Vérifiez la cote du trou sur votre propre douille.",
  "vaseCheck.lampStanding": "Debout : fixez la douille dans le trou du fond (Ø {mm} mm) avec la bague d'abat-jour ; le câble passe par le pied creux. Choisissez un pied assez haut pour que le corps de la douille tienne dessous – mesurez-le.",
