  "vaseCheck.slitsKept": "Trancheur : mode vase en spirale activé, largeur de ligne extérieure {line} mm (comme réglé ici). Les fentes ({slit} mm) sont conservées avec les réglages par défaut ; les deux lignes d'une nervure sont à {slit} mm l'une de l'autre. Fusion complète : largeur de fente 0,03 mm et « Slice gap closing radius » à 0,01 mm dans le trancheur (PrusaSlicer, OrcaSlicer, Bambu Studio).",
  "vaseCheck.slitsGap": "Trancheur : mode vase en spirale activé, largeur de ligne extérieure {line} mm (comme réglé ici). Important : réglez « Slice gap closing radius » (PrusaSlicer, OrcaSlicer, Bambu Studio) à {radius} mm au plus – sinon le trancheur ferme les fentes de {slit} mm et imprime une paroi simple.",
