  "export.stl.note": "Idéal pour les trancheurs et l'impression 3D. La géométrie est exportée sous forme de maillage triangulé. Dans Chrome et Edge, vous choisissez le dossier et le nom une seule fois ; les exportations STL ultérieures de la conception écrivent dans ce fichier, sauf si vous tapez un autre nom : vous serez alors invité à nouveau.",
