  "export.3mf.description": "Projet Slicer avec des couleurs",
  "export.3mf.note": "Pour PrusaSlicer, Bambu Studio, OrcaSlicer et Cura. Chaque corps reste une pièce à part avec son nom et sa couleur.",
  "export.obj.description": "Maillage 3D universel",
  "export.obj.note": "Un format de maillage largement compatible pour la modélisation, le rendu et l'échange. Les couleurs sont stockées aux sommets que Bambu Studio et OrcaSlicer lisent.",
  "export.step.description": "CAO / B-Rep",
  "export.step.note": "Conserve les boîtes, les cylindres, les sphères et les cônes sous forme de géométrie CAO précise, ainsi que tout ce dont les bords ont été arrondis ou chanfreinés et les corps entrés en STEP. Les fils, les ressorts et les engrenages correspondent également à leur corps exact. Les formes effilées, penchées et torsadées conviennent également. Le texte part aussi exact, lettre par lettre avec les courbes de la police. Les maillages importés partent rendus exacts, leurs plans, cylindres, cônes, sphères et tores en vraies faces ; un maillage de forme libre, comme une figurine, part en STL.",
  "export.svg.description": "Vecteur vue de dessus",
  "export.svg.note": "Exporte une silhouette nette en vue de dessus en millimètres, comprenant des trous et des contours incurvés.",
  "export.svg.noteFootprint": "Exporte seulement les contours par lesquels les objets reposent sur le plan de travail, en lignes en millimètres, pour la découpe laser et les gabarits.",
  "export.svg.noteEdges": "Exporte les arêtes visibles du dessus en lignes, en millimètres, chaque corps dans sa couleur : contours, trous, poches et gravures, chaque surface fermée, pour la gravure laser et les traceurs.",
  "export.svg.view": "Vue",
