  "export.bridgeWidth": "Largeur des ponts",
  "export.bridgeCount": "Ponts par partie",
  "export.svg.viewEdges": "Arêtes visibles du dessus",
  "export.dxf.description": "Contour pour découpe laser",
  "export.dxf.note": "Exporte le contour vu de dessus pour les ateliers de découpe laser : lignes, vrais arcs et cercles sur le calque 0 en blanc, en millimètres. Les corps qui se touchent forment un seul contour.",
  "export.dxf.noteFootprint": "Exporte seulement les contours par lesquels les objets reposent sur le plan de travail, pour les ateliers de découpe laser : lignes, vrais arcs et cercles sur le calque 0 en blanc, en millimètres.",
  "export.lyl.description": "Format de conception natif de layerling",
  "export.lyl.note": "Conserve la conception modifiable, l'historique d'annulation/rétablissement, les esquisses, les groupes, les données CAO et les sources importées. Les fichiers .skf plus anciens s'ouvrent également et sont enregistrés au format .lyl. Dans Chrome et Edge, vous choisissez le dossier et vous nommez vous-même, puis Ctrl+S enregistre à nouveau dans ce fichier ; un dessin ouvert à partir d'un fichier y est réenregistré.",
